def solve(inputs: dict) -> float:
    n = inputs['n']  # number of people
    k = inputs['k']  # every k-th person is eliminated

    # Josephus problem: find survivor position (1-indexed)
    def josephus(n, k):
        # Start with positions 0 to n-1, then convert to 1-indexed
        survivor = 0
        for i in range(2, n + 1):
            survivor = (survivor + k) % i
        return survivor + 1  # Convert to 1-indexed

    result = josephus(n, k)
    return float(result)

